// The relays-only view: one copy, used twice. The JARVIS phone app sends through
// /api/phone/limbs; the wall box's own page (web_page.h, generated by board_page.py from
// this file) sends to the board's /relay with its token. Same tiles, same rules:
//
//   * A tile shows what the BOARD last reported, never what was asked: cyan = the board
//     confirms on, dark = the board confirms off, amber = asked, not confirmed yet.
//   * Taps settle for 150 ms and the last one wins: five taps in a second send one
//     command (the opposite of what the board reports, if the taps net to a change).
//     A coil that switches on every tap browned the BlackBerry supply out (6 Nov).
//   * One command per relay in flight; a tap during it is sent when it returns.
//   * No reply within 6 s: the tile says "not confirmed" instead of guessing.
'use strict'

const RELAY_SETTLE_MS = 150
const RELAY_CONFIRM_MS = 6000
// Device colours stay the same in every section and on the board (plan WP5).
const RELAY_COLOURS = {
  light: '#ffffff', fan: '#5ce1ff', light2: '#ffb347', light3: '#ffb347',
  light4: '#ff5fa8', light5: '#ff5fa8', light6: '#ffffff', light7: '#a78bfa'
}

// root: an element to draw into. send(id, on): a Promise that resolves once the request
// was accepted (a confirmation arrives later through update()) or rejects with an Error.
function RelayPanel(root, send) {
  // id -> {id, name, kind, on (board report), available, wanted (tapped, not sent yet),
  //        sent (sent, not confirmed yet), inflight, timer, since, error}
  const rows = new Map()
  const order = []

  function row(id) {
    let r = rows.get(id)
    if (!r) {
      r = { id, name: id, kind: '', on: null, available: true, wanted: null, sent: null, inflight: false, timer: 0, since: 0, error: '' }
      rows.set(id, r)
      order.push(id)
    }
    return r
  }

  // list: [{id, name, kind, on (the board's report: true / false / null), available}]
  function update(list) {
    for (const d of list) {
      const r = row(d.id)
      r.name = d.name || d.id
      r.kind = d.kind || ''
      r.on = d.on === true ? true : d.on === false ? false : null
      r.available = d.available !== false
      if (r.sent !== null && r.sent === r.on) { r.sent = null; r.error = '' }
    }
    draw()
  }

  function tap(id) {
    const r = rows.get(id)
    if (!r || !r.available) return
    const base = r.wanted !== null ? r.wanted : expected(r)
    r.wanted = !base
    r.error = ''
    clearTimeout(r.timer)
    r.timer = setTimeout(() => flush(r), RELAY_SETTLE_MS)
    draw()
  }

  // What the relay will be once nothing more is sent: the unconfirmed command, else the report.
  function expected(r) { return r.sent !== null ? r.sent : r.on }

  function flush(r) {
    if (r.wanted === null || r.inflight) return
    const target = r.wanted
    r.wanted = null
    if (target === expected(r)) { draw(); return }            // the taps netted out
    r.inflight = true
    r.sent = target
    r.since = Date.now()
    draw()
    Promise.resolve()
      .then(() => send(r.id, target))
      .catch((e) => { r.error = (e && e.message) || 'failed'; r.sent = null; r.wanted = null })
      .finally(() => {
        r.inflight = false
        flush(r)                                                 // a tap made meanwhile
        draw()
      })
  }

  function stateOf(r) {
    if (!r.available) return ['off', 'unavailable']
    if (r.error) return ['fault', r.error]
    const goal = r.wanted !== null ? r.wanted : r.sent
    if (goal !== null && goal !== r.on) {
      if (r.wanted === null && Date.now() - r.since > RELAY_CONFIRM_MS) return ['fault', 'not confirmed']
      return ['wait', goal ? 'turning on…' : 'turning off…']
    }
    if (r.on === null) return ['off', 'no report from the board']
    return [r.on ? 'on' : 'off', r.on ? 'on · confirmed' : 'off · confirmed']
  }

  function draw() {
    root.textContent = ''
    for (const id of order) {
      const r = rows.get(id)
      const [cls, text] = stateOf(r)
      const b = document.createElement('button')
      b.type = 'button'
      b.className = 'relay ' + cls
      b.disabled = !r.available
      b.style.setProperty('--dev', RELAY_COLOURS[r.id] || '#5ce1ff')
      b.setAttribute('aria-pressed', String(r.on === true))
      b.setAttribute('aria-busy', String(cls === 'wait'))
      const name = document.createElement('span'); name.className = 'relay-name'; name.textContent = r.name
      const sub = document.createElement('span'); sub.className = 'relay-sub'; sub.textContent = text
      b.append(name, sub)
      b.addEventListener('click', () => tap(r.id))
      root.append(b)
    }
  }

  // Re-check "not confirmed" while nothing else redraws.
  setInterval(() => { for (const r of rows.values()) if (r.sent !== null) { draw(); break } }, 1000)

  return { update, tap }
}
